void row_kernel(const T* __restrict__ Q, const T* __restrict__ K, const T* __restrict__ V,
                T* __restrict__ O, int total_rows, int N, int D) {
    int g = blockIdx.x;
    if (g >= total_rows) return;
    int tid = threadIdx.x;
    int bh = g / N;
    int row = g - bh * N;
    size_t base = ((size_t)bh * N) * D;
    const T* q = Q + base + (size_t)row * D;
    const T* kbase = K + base;
    const T* vbase = V + base;
    T* o = O + base + (size_t)row * D;
