        for (int d = tid; d < D; d += BLOCK) part += to_float<T>(q[d]) * to_float<T>(kbase[(size_t)j * D + d]);
        float s = block_sum<BLOCK>(part) * scale;
        float mn = fmaxf(m, s);
        float a = __expf(m - mn);
        float p = __expf(s - mn);
        if (tid < D) acc = acc * a + p * to_float<T>(vbase[(size_t)j * D + tid]);
        l = l * a + p;
        m = mn;
    }
    if (tid < D) o[tid] = from_float<T>(acc / l);
