template<typename T>
__global__ void softmax_to_kernel(float* __restrict__ S, T* __restrict__ P, int rows, int N) {
    int r = blockIdx.x;
    if (r >= rows) return;
    int tid = threadIdx.x;
    float* row = S + (size_t)r * N;
    T* prow = P + (size_t)r * N;

    float m = -INFINITY;
    for (int c = tid; c < N; c += blockDim.x) m = fmaxf(m, row[c]);
    __shared__ float sm[256];
    sm[tid] = m;
    __syncthreads();
    for (int s = 128; s > 0; s >>= 1) {
        if (tid < s) sm[tid] = fmaxf(sm[tid], sm[tid + s]);
        __syncthreads();
